var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var st := "hits" if str(H.phase().resolution_state.get("stage", "")) == "hits_pending" else "wounds"
print("[cus11e prime] dock paused at ", H.phase().resolution_state.get("stage", ""))
return H.phase()._cus11e_reroll_label(st).begins_with("PRIME TARGET (free)")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var ph = H.phase()
var hitp := str(ph.resolution_state.get("stage", "")) == "hits_pending"
var st := "hits" if hitp else "wounds"
var rolls: Array = ph.resolution_state.get("staged_hit_context", {}).get("hit_rolls", []) if hitp else ph.resolution_state.get("staged_wound_context", {}).get("wound_rolls", [])
var idx := 0
for i in range(rolls.size()):
	if int(rolls[i]) < int(rolls[idx]):
		idx = i
var r = ph.execute_action({"type": "USE_SHOOTING_REROLL", "player": 1, "payload": {"stage": st, "die_index": idx}})
print("[cus11e prime] re-roll ", st, " die ", idx, " of ", rolls, ": ", r.get("success", false), " ", r.get("error", ""))
H.main().set_meta("cus11e_pt_stage", "hit" if hitp else "wound")
return r.get("success", false)

